<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {RouterLink} from 'vue-router';import {configured} from '../lib/supabase';import {list,settings,price,money,imageUrl,whatsapp,logoDefault,heroDefault,type Product,type Category,type Settings,type Frete,type Banner} from '../lib/catalog';
const products=ref<Product[]>([]),cats=ref<Category[]>([]),fretes=ref<Frete[]>([]),banners=ref<Banner[]>([]),config=ref<Settings|null>(null),error=ref(''),loading=ref(true),search=ref(''),category=ref('all'),delivery=ref(''),express=ref(false),cartOpen=ref(false);
type CartItem={id:string;nome:string;preco:number;qty:number};const cart=ref<CartItem[]>([]);
try{const stored=localStorage.getItem('flores-sacola-vue');if(stored)cart.value=JSON.parse(stored);}catch{}
watch(cart,v=>localStorage.setItem('flores-sacola-vue',JSON.stringify(v)),{deep:true});
onMounted(async()=>{if(!configured){error.value='Conexão Supabase não configurada. Consulte o README para configurar o arquivo .env.';loading.value=false;return;}try{const [p,c,f,b,s]=await Promise.all([list<Product>('digital_catalog_products'),list<Category>('digital_catalog_categories'),list<Frete>('fretes_cidades'),list<Banner>('digital_catalog_banners'),settings()]);products.value=p;cats.value=c;fretes.value=f;banners.value=b;config.value=s;}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{loading.value=false;}});
const filtered=computed(()=>products.value.filter(p=>(category.value==='all'||p.categoria_id===category.value||p.categoria===cats.value.find(c=>c.id===category.value)?.nome)&&p.nome.toLowerCase().includes(search.value.trim().toLowerCase())));
const sub=computed(()=>cart.value.reduce((s,p)=>s+p.preco*p.qty,0));const selectedFrete=computed(()=>fretes.value.find(f=>f.id===delivery.value));const freight=computed(()=>{const f=selectedFrete.value;if(!f||f.estrategia!=='cobrar_valor')return 0;return (express.value?Number(f.custo_expresso)||Number(f.custo):Number(f.custo))||0;});const total=computed(()=>sub.value+freight.value);
const phone=computed(()=>config.value?.whatsapp_vendas||'5519993614366');const message=computed(()=>['Olá! Vim pelo catálogo da Shopping de Flores e gostaria de fazer um pedido:','',...cart.value.map(p=>`• ${p.qty} × ${p.nome} — ${money(p.preco*p.qty)}`),'',`Subtotal: ${money(sub.value)}`,...(selectedFrete.value?[`Entrega: ${selectedFrete.value.cidade}${express.value?' (expressa)':''}`,`Frete: ${money(freight.value)}`]:[]),`Total: ${money(total.value)}`].join('\n'));
function add(p:Product){const row=cart.value.find(i=>i.id===p.id);if(row)row.qty++;else cart.value.push({id:p.id,nome:p.nome,preco:price(p),qty:1});cartOpen.value=true;}
function remove(id:string){cart.value=cart.value.filter(i=>i.id!==id);}
</script>
<template><header class="header"><div class="container header-inner"><RouterLink to="/" class="brand"><img :src="imageUrl(config?.logo_url)||logoDefault" alt="Logo Shopping de Flores"/> <span>Shopping <strong>de Flores</strong></span></RouterLink><nav><a href="#produtos">Flores e presentes</a><a :href="whatsapp(phone,'Olá! Gostaria de ajuda com o catálogo.')" target="_blank" rel="noopener">Fale conosco</a><RouterLink to="/admin/catalogo">Gerenciar</RouterLink></nav><button class="cart-button" @click="cartOpen=!cartOpen">Sacola ({{cart.reduce((s,i)=>s+i.qty,0)}})</button></div></header>
<section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="eyebrow">SHOPPING DE FLORES · CATÁLOGO DIGITAL</div><h1>Flores para <em>momentos inesquecíveis.</em></h1><p>{{config?.texto_topo||'Celebre, surpreenda e demonstre carinho. Escolha suas flores favoritas e fale diretamente com nossa equipe.'}}</p><a class="btn primary" href="#produtos">Descobrir presentes <span>↗</span></a><div class="muted">{{config?.texto_secundario||'Feito com carinho, para quem faz a vida florescer.'}}</div></div><img :src="imageUrl(banners[0]?.imagem_desktop)||heroDefault" alt="Flores do Shopping de Flores" class="hero-photo"/></div></section>
<section id="produtos" class="container section"><div class="eyebrow">ESCOLHAS ESPECIAIS</div><h2>Um gesto que <em>floresce.</em></h2><p class="subtitle">Encontre o presente perfeito para cada ocasião.</p><div class="filters"><input v-model="search" placeholder="Buscar buquês, flores e presentes..." aria-label="Buscar produtos"/><select v-model="category" aria-label="Filtrar categoria"><option value="all">Todas as categorias</option><option v-for="c in cats" :key="c.id" :value="c.id">{{c.nome}}</option></select></div><p v-if="loading" class="notice">Carregando catálogo...</p><p v-if="error" class="notice error">{{error}}</p><p v-else-if="!loading && !filtered.length" class="notice">Nenhum produto encontrado nesta seleção.</p><div class="products"><article v-for="p in filtered" :key="p.id" class="product"><RouterLink :to="`/catalogo/produto/${p.slug||p.id}`" class="product-photo"><img v-if="p.imagem_url" :src="imageUrl(p.imagem_url)" :alt="p.nome" loading="lazy"/><div v-else class="placeholder">🌷</div><span v-if="p.preco_promocional&&p.preco_promocional<p.preco" class="offer">OFERTA</span></RouterLink><div class="eyebrow tiny">{{p.categoria||cats.find(c=>c.id===p.categoria_id)?.nome||'FLORES'}}</div><RouterLink :to="`/catalogo/produto/${p.slug||p.id}`" class="product-name">{{p.nome}}</RouterLink><div class="price"><strong>{{money(price(p))}}</strong><del v-if="price(p)<p.preco">{{money(p.preco)}}</del></div><button class="btn outline full" @click="add(p)">Adicionar à sacola +</button></article></div></section>
<section class="banner"><div class="container"><div class="eyebrow">TUDO PARA MOMENTOS INESQUECÍVEIS</div><h2>O carinho mora nos <em>detalhes.</em></h2><a class="btn primary" :href="whatsapp(phone,'Olá! Gostaria de escolher um presente especial.')" target="_blank" rel="noopener">Conversar com a equipe ↗</a></div></section><footer class="footer"><div class="container"><strong>Shopping de Flores</strong><p>Tudo para momentos inesquecíveis.</p><small>© {{new Date().getFullYear()}} Shopping de Flores</small></div></footer>
<div v-if="cartOpen" class="backdrop" @click.self="cartOpen=false"><aside class="cart"><div class="cart-heading"><h2>Sua sacola</h2><button @click="cartOpen=false">✕</button></div><p v-if="!cart.length">Sua sacola está vazia.</p><div class="cart-item" v-for="i in cart" :key="i.id"><div><strong>{{i.nome}}</strong><small>{{money(i.preco)}} cada</small></div><div class="qty"><button @click="i.qty>1?i.qty--:remove(i.id)">−</button><b>{{i.qty}}</b><button @click="i.qty++">+</button></div></div><template v-if="cart.length"><label class="field">Cidade de entrega<select v-model="delivery"><option value="">Escolha a cidade</option><option v-for="f in fretes" :key="f.id" :value="f.id">{{f.cidade}}</option></select></label><label v-if="config?.entrega_expressa" class="field inline"><input type="checkbox" v-model="express"/> Entrega expressa</label><div class="totals"><span>Subtotal</span><b>{{money(sub)}}</b><span>Frete</span><b>{{delivery?money(freight):'A definir'}}</b><strong>Total</strong><strong>{{money(total)}}</strong></div><a class="btn primary full" :href="whatsapp(phone,message)" target="_blank" rel="noopener">Finalizar pelo WhatsApp ↗</a><p class="fine">O pedido é enviado para nossa equipe pelo WhatsApp. Não há cobrança automática nesta versão.</p></template></aside></div>
</template>